function mk(t, attrs){attrs["font-family"]=FF;return el("text",attrs,t);}
var data=[4529.9,4481.5,4396.4,4414.6,4539.9,4476.6,4439.0,4460.7,4407.3,4408.9,4351.9,4332.8,4387.5,4399.7,4424.9,4383.9,4376.4,4318.4,4298.0,4321.2,4168.4];
